    "decision": "insufficient_evidence",
    "evidence": "The trace ends abruptly after a reviewer comment without explicit system shutdown or completion signaling visible.",
    "quotes": []
  },
  "conversation_reset": {
    "decision": "absent",
    "evidence": "There was no dialogue reset or restart during the interaction.",
    "quotes": []
